package handlers

// Generated by auditor/verify.py to test one claim. Asserts what the
// specification promises, so a failure is the drift and a pass refutes the
// claim. Regenerated per claim; not intended to be committed.

import (
	"encoding/json"
	"net/http/httptest"
	"sort"
	"strings"
	"testing"
)

// Not every assertion template uses every import; Go treats an unused import as
// a compile error, and a test that fails to build would otherwise be
// indistinguishable from a claim that could not be confirmed.
var (
	_ = strings.NewReader
	_ = json.Unmarshal
	_ = sort.Strings
	_ = strings.TrimSpace
	_ = toNumber
)

func keys(m map[string]any) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

func headerNames(h map[string][]string) []string {
	out := make([]string, 0, len(h))
	for k := range h {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// firstObject unwraps a top-level array so a list endpoint is judged by the
// shape of its elements, which is what the spec describes.
func firstObject(v any) map[string]any {
	switch t := v.(type) {
	case map[string]any:
		return t
	case []any:
		if len(t) > 0 {
			if obj, ok := t[0].(map[string]any); ok {
				return obj
			}
		}
	}
	return nil
}

func toNumber(v any) float64 {
	if f, ok := v.(float64); ok {
		return f
	}
	return -1
}

func jsonType(v any) string {
	switch v.(type) {
	case string:
		return "string"
	case bool:
		return "boolean"
	case float64:
		return "number"
	case []any:
		return "array"
	case map[string]any:
		return "object"
	}
	return "null"
}

func TestContractVerify(t *testing.T) {
	req := httptest.NewRequest("POST", "/customers", strings.NewReader("{\"email\": \"test@example.test\", \"firstName\": \"test-firstname\", \"lastName\": \"test-lastname\", \"phone\": \"+2348000000000\"}"))
	req.Header.Set("X-Api-Key", "test-key")
	req.SetPathValue("id", "test-id")
	rec := httptest.NewRecorder()
	CreateCustomer(rec, req)

	if rec.Code != 201 {
		t.Fatalf("spec documents 201 on success; handler returned %d", rec.Code)
	}
}
